const devices = ['USB microphone', 'USB camera', 'digital voice recorder', 'portable projector'];
const query = document.querySelector('#equipment-query');
const list = document.querySelector('#equipment-results');
const count = document.querySelector('#equipment-count');
const empty = document.querySelector('#equipment-empty');

function renderDevices(matches) {
  list.replaceChildren();
  for (const device of matches) {
    const row = document.createElement('li');
    row.textContent = device;
    list.append(row);
  }
  count.textContent = matches.length + ' devices found';
  empty.hidden = matches.length !== 0;
}

query.addEventListener('input', () => {
  const keyword = query.value.trim().toLowerCase();
  const matches = [];
  for (const device of devices) {
    if (device.toLowerCase().includes(keyword)) {
      matches.push(device);
    }
  }
  renderDevices(matches);
});

renderDevices(devices);

project-budget.script.js:
const budgetInCents = 30000;
const expenses = [];
const amount = document.querySelector('#expense-amount');
const addExpense = document.querySelector('#add-expense');
const total = document.querySelector('#expense-total');
const remaining = document.querySelector('#expense-remaining');
const error = document.querySelector('#expense-error');

function formatAmount(cents) {
  return (cents / 100).toFixed(2) + ' yuan';
}

function renderBudget() {
  const spent = expenses.reduce((sum, cents) => sum + cents, 0);
  total.textContent = formatAmount(spent);
  remaining.textContent = formatAmount(budgetInCents - spent);
}

addExpense.addEventListener('click', () => {
  if (!amount.checkValidity()) {
    error.textContent = 'Please enter an amount greater than 0 and with up to two decimal places.';
    return;
  }
  const cents = Math.round(Number(amount.value) * 100);
  expenses.push(cents);
  error.textContent = '';
  amount.value = '';
  renderBudget();
});

renderBudget();

project-flashcards.script.js:
const cards = [
  { question: 'Which HTML tag represents a hyperlink?', answer: '<a>' },
  { question: 'Which CSS property sets text color?', answer: 'color' },
  { question: 'What is the subscript of the first element of the array?', answer: '0' },
];
const position = document.querySelector('#card-position');
const question = document.querySelector('#card-question');
const answer = document.querySelector('#card-answer');
const flip = document.querySelector('#flip-card');
const next = document.querySelector('#next-card');
let cardIndex = 0;
let answerSide = false;

function renderCard() {
  const card = cards[cardIndex];
  question.textContent = card.question;
  answer.textContent = card.answer;
  question.hidden = answerSide;
  answer.hidden = !answerSide;
  position.textContent = (cardIndex + 1) + ' / ' + cards.length;
  flip.textContent = answerSide ? 'Return to question' : 'Show answer';
  flip.setAttribute('aria-expanded', String(answerSide));
}

flip.addEventListener('click', () => {
  answerSide = !answerSide;
  renderCard();
});

next.addEventListener('click', () => {
  cardIndex += 1;
  if (cardIndex === cards.length) {
    cardIndex = 0;
  }
  answerSide = false;
  renderCard();
});

renderCard();

project-event-board.script.js:
const events = [
  { id: 'print', title: 'Printmaking Workshop', category: 'workshop', showtime: '09:30 · Workshop' },
  { id: 'museum', title: 'School History Museum Guide', category: 'tour', showtime: '10:00 · Tour' },
  { id: 'sound', title: 'sound editing experience', category: 'workshop', showtime: '13:30 · Workshop' },
  { id: 'garden', title: 'Botanical Garden Guide', category: 'tour', showtime: '14:00 · Tour' },
];
const category = document.querySelector('#event-category');
const list = document.querySelector('#event-list');
const storageKey = 'campusEventFavorites';
let favorites = JSON.parse(localStorage.getItem(storageKey) ?? '[]');

function toggleFavorite(id, button) {
  const index = favorites.indexOf(id);
  if (index === -1) {
    favorites.push(id);
  } else {
    favorites.splice(index, 1);
  }
  localStorage.setItem(storageKey, JSON.stringify(favorites));
  button.setAttribute('aria-pressed', String(favorites.includes(id)));
}

function renderEvents() {
  const selected = category.value;
  const visible = selected === 'all' ? events : events.filter((event) => event.category === selected);
  list.replaceChildren();
  for (const event of visible) {
    const row = document.createElement('li');
    row.className = 'event';
    row.dataset.eventId = event.id;
    row.dataset.category = event.category;

    const information = document.createElement('div');
    const title = document.createElement('h2');
    title.textContent = event.title;
    const when = document.createElement('p');
    when.textContent = event.showtime;
    information.append(title, when);

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'favorite-button';
    button.textContent = 'Collection';
    button.setAttribute('aria-label', 'Collection ' + event.title);
    button.setAttribute('aria-pressed', String(favorites.includes(event.id)));
    button.addEventListener('click', () => toggleFavorite(event.id, button));
    row.append(information, button);
    list.append(row);
  }
}

category.addEventListener('change', renderEvents);
renderEvents();
